import './navigation.mjs';
const $=id=>document.getElementById(id),assetRoot=new URL('./tatari-data/',import.meta.url);
const text=value=>typeof value==='string'?value:value?.en||value?.zh||'';
const image=(src,alt,cls)=>{const img=document.createElement('img');if(src)img.src=new URL(src,assetRoot);img.alt=alt;img.className=cls||'';return img;};
const el=(tag,content,cls)=>{const node=document.createElement(tag);if(content!==undefined)node.textContent=content;if(cls)node.className=cls;return node;};
let data,selected,evolution=1,mode='normal',element=null;

const names={2:'Water',3:'Fire',4:'Grass',5:'Electric',6:'Earth'};
import {searchMatches,minimumStars,calculatedStats,databaseDefaults,compactStat} from './tatari-model.mjs';

function roster(){const entries=data.units.filter(u=>(!element||u.element===element)&&searchMatches(u,$('tatari-search').value));$('roster-count').textContent=entries.length+' Tier 1 Tatari v'+data.version;$('tatari-roster').replaceChildren(...entries.map(u=>{const base=u.forms.find(f=>f.evolution===1),button=el('button',undefined,'roster-card');button.type='button';button.setAttribute('aria-label','Show '+text(base.name));button.setAttribute('aria-pressed',String(u.id===selected?.id));button.append(image(u.elementImage,names[u.element]||'Unknown element','roster-element'),image(u.roleImage,text(u.role),'roster-role'),image(base.portrait,text(base.name),'roster-portrait'),el('span',text(base.name)));button.onclick=()=>{selected=u;evolution=1;render();roster();updateLink();};return button;}));if(!entries.length)$('tatari-roster').append(el('p','No Tatari matches. Try another name or clear the element filter.','roster-empty'));}
function updateLink(){const url=new URL(location.href);url.searchParams.set('tatari',selected.id);url.searchParams.set('tier',evolution);url.searchParams.set('skills',mode);history.replaceState(null,'',url);}
function starDisplay(n){const box=el('div',undefined,'star-display');if(Number.isInteger(n)&&n>0&&n<=84)box.append(image('stars/'+String(n).padStart(2,'0')+'.png',n+' stars','star-level-image'));else if(n===null)box.textContent='Not recorded';return box;}
function stars(n){return n===null?'Not recorded':n===0?'0 stars':n<=6?'★'.repeat(n):n+' ★';}
function render(){const f=selected.forms.find(f=>f.evolution===evolution),min=minimumStars(selected,f);$('evolution-list').replaceChildren(...selected.forms.map(form=>{const button=el('button',undefined,'evolution-button');button.type='button';button.setAttribute('aria-pressed',String(form.evolution===evolution));button.setAttribute('aria-label',text(form.name)+' · tier '+form.evolution);button.append(image(form.playerhead,text(form.name)),el('span',text(form.name)));button.onclick=()=>{evolution=form.evolution;render();updateLink();};return button;}));const max=f.evolution===Math.max(...selected.forms.map(f=>f.evolution));const evoArt=el('div',undefined,'evo-requirement-art');evoArt.append(image('images/evo.png','Evolution badge','evo-badge'));if(!max)evoArt.append(starDisplay(f.trial?.requiredStars??null));$('next-evolution').replaceChildren(evoArt,el('span',max?'Already at max tier':f.trial?.requiredStars!=null?'Reach Star Lv.'+f.trial.requiredStars+' to Evo':'Evolution requirement not recorded'));const title=el('div',undefined,'profile-heading'),badges=el('div',undefined,'profile-badges');badges.append(image(selected.elementImage,names[selected.element]),image(selected.roleImage,text(selected.role)));title.append(el('h1',text(f.name)),badges);const stats=el('div',undefined,'base-stats');const defaults=databaseDefaults(selected,f);if(defaults.stars!==null&&defaults.foodStage!==null){const values=calculatedStats(data,selected,f,defaults),feed=selected.feedingStages.find(r=>r.stage===defaults.foodStage);for(const a of ['ATK','HP','DEF']){const tile=el('div',undefined,'stat-tile'),grade=({0:'E',5:'D',10:'C',25:'B',40:'A',50:'S',55:'SS',60:'SSS'})[feed[a+'PR']],art=el('div',undefined,'food-stat-art');if(grade)art.append(image('food-stats/'+grade+a.toLowerCase()+'.png',grade+' '+a+' food grade','food-stat-icon'));const value=el('strong',compactStat(values[a]),'food-stat-value');value.setAttribute('aria-label',a+' '+compactStat(values[a]));art.append(value);tile.append(art);stats.append(tile);}}else stats.append(el('p','Evolution requirements not recorded.','baseline'));$('tatari-profile').replaceChildren(image(f.portrait,text(f.name),'detail-portrait'),starDisplay(min),title,el('p',text(f.lore)||text(f.description),'profile-lore'),stats,el('p','Stats based on level 500 Tatari with their evolution requirements applied.','food-note'));renderSkills();}
function renderSkills(){for(const m of ['normal','horde']){const button=$(m+'-skills');button.setAttribute('aria-selected',String(mode===m));button.tabIndex=mode===m?0:-1;}$('skill-panel').setAttribute('aria-labelledby',mode+'-skills');const f=selected.forms.find(f=>f.evolution===evolution);$('skill-list').replaceChildren(...f.skills[mode].map(s=>{const card=el('article',undefined,'skill-card');card.append(el('h2',text(s.name)),image(s.image,text(s.name)),el('p',text(s.description)));if(s.details.length){const list=el('ul');for(const d of s.details)list.append(el('li',[text(d.title),text(d.text)].filter(Boolean).join(': ')));card.append(list);}return card;}));if(!f.skills[mode].length)$('skill-list').append(el('p','No '+mode+' skills recorded.'));if(mode==='horde')$('skill-list').append(el('p','Horde skill availability depends on evolution and Horde progression.','horde-note'));}
for(const m of ['normal','horde']){$(m+'-skills').onclick=()=>{mode=m;renderSkills();updateLink();};$(m+'-skills').onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();mode=e.key==='Home'?'normal':e.key==='End'?'horde':mode==='normal'?'horde':'normal';renderSkills();$(mode+'-skills').focus();updateLink();}};}
$('tatari-search').oninput=()=>{if(data)roster();};
try{const response=await fetch(new URL('roster.json',assetRoot));if(!response.ok)throw Error('Tatari data could not be loaded.');data=await response.json();const params=new URLSearchParams(location.search);selected=data.units.find(u=>u.id===Number(params.get('tatari')))||data.units.find(u=>u.id===11)||data.units[0];evolution=selected.forms.some(f=>f.evolution===Number(params.get('tier')))?Number(params.get('tier')):1;mode=params.get('skills')==='horde'?'horde':'normal';for(const id of [3,4,6,5,2]){const unit=data.units.find(u=>u.element===id),button=el('button');button.type='button';button.setAttribute('aria-label','Filter '+names[id]);button.setAttribute('aria-pressed','false');button.append(image(unit.elementImage,names[id]));button.onclick=()=>{element=element===id?null:id;[...$('element-filters').children].forEach(b=>b.setAttribute('aria-pressed',String(b===button&&element!==null)));roster();};$('element-filters').append(button);}roster();render();}catch(error){$('database-status').textContent=error.message;$('database-status').setAttribute('role','alert');}
